import React from 'react';

import { deleteWorkoutPhotoAsync } from '@apps/Workouts/@services/workoutsPhoto.service';
import { IWorkoutPhotoFull } from '@apps/Workouts/@types/workouts.types';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import WorkoutPhotoAddForm from './WorkoutPhotoAddForm';
import WorkoutPhotoEditForm from './WorkoutPhotoEditForm';
import WorkoutPhotoItem from './WorkoutPhotoItem';

interface IWorkoutPhotosProps extends React.HTMLAttributes<HTMLDivElement> {
  id_workout: number;
  photos: IWorkoutPhotoFull[];
  onChangePhotos: (newPhotos: IWorkoutPhotoFull[]) => void;
  canEdit?: boolean;
}

const WorkoutPhotos: React.FC<IWorkoutPhotosProps> = ({
  id_workout,
  photos,
  onChangePhotos,
  canEdit,
  ...rest
}) => {
  const handleEditPhoto = (photo: IWorkoutPhotoFull) => {
    showModal({
      title: 'Редактирование фото',
      style: { minWidth: 600 },
      size: 'lg',
      children: (clos: any) => {
        return (
          <WorkoutPhotoEditForm
            id_workout={id_workout}
            photo={photo}
            callback={(newItem) => {
              clos();
              onChangePhotos(photos.map((p) => (p.id === photo.id ? newItem : p)));
            }}
          />
        );
      },
    });
  };
  const handleDeletePhoto = async (photo: IWorkoutPhotoFull) => {
    if (await confirmModal2(`Удалить фото?`)) {
      await deleteWorkoutPhotoAsync(photo.id);
      onChangePhotos(photos.filter((p) => p.id !== photo.id));
      notificationHelper.success('Удалено');
    }
  };

  return (
    <section {...rest}>
      {photos.length > 0 ? (
        <PohRow className="mb-3 flex-wrap">
          {photos.map((photo) => {
            return (
              <PohCol sm={6} key={photo.id} className="mb-3">
                <WorkoutPhotoItem
                  photo={photo}
                  key={photo.id}
                  toolbar={
                    canEdit ? (
                      <div className="d-flex align-items-center" style={{ gap: 4 }}>
                        {photo.coordinates && (
                          <PohButton
                            icon={IconsEnum['map-marker']}
                            onClick={() =>
                              photo.coordinates &&
                              window.open(`geo:${photo.coordinates.slice(0, 2).join(',')}`)
                            }
                            title={photo.coordinates.slice(0, 2).join(', ')}
                            size={ButtonSize.Small}
                          />
                        )}

                        <PohButton
                          icon={IconsEnum.edit}
                          className="ms-auto"
                          onClick={() => handleEditPhoto(photo)}
                          size={ButtonSize.Small}
                        />
                        <PohButton
                          icon={IconsEnum.trash}
                          onClick={() => handleDeletePhoto(photo)}
                          size={ButtonSize.Small}
                        />
                      </div>
                    ) : null
                  }
                />
              </PohCol>
            );
          })}
        </PohRow>
      ) : (
        <small className="d-block p-2 text-muted text-center">
          Нет фоток. {canEdit && 'Можно добавить'}
        </small>
      )}
      {canEdit && (
        <WorkoutPhotoAddForm
          id_workout={id_workout}
          callback={(newItem) => {
            onChangePhotos([...photos, newItem]);
          }}
        />
      )}
    </section>
  );
};

export default WorkoutPhotos;
