import { handleApiError, post } from '@helpers/httpClient';

import { IWorkoutPhotoAddDTO, IWorkoutPhotoUpdateDTO } from '../@types/DTO/workouts.dto.types';

export const addWorkoutPhotoAsync = async (data: IWorkoutPhotoAddDTO) => {
  return post('/ajax/workouts/workout_photos_add.php', data).then<{ id: number }>(handleApiError);
};

export const editWorkoutPhotoAsync = async (data: IWorkoutPhotoUpdateDTO) => {
  return post('/ajax/workouts/workout_photos_edit.php', data).then<{ id: number }>(handleApiError);
};

export const deleteWorkoutPhotoAsync = async (id: number) => {
  return post('/ajax/workouts/workout_photos_del.php', { id }).then<{ affected: number }>(
    handleApiError,
  );
};
